 <div class="touch"><button data-key="left">◀</button><button data-key="jump">▲</button><button data-key="right">▶</button></div><div class="touch-right"><button id="touchMine">MINAR</button><button id="touchPlace">PONER</button></div><div class="toast" id="toast"></div>
 <div class="modal-back" id="modal"><section class="modal"><button class="close" id="closeModal">✕</button><h2>Atlas de Brumaria</h2><p>Diez tierras, diez formas de vida. Cada frontera cambia la luz, el suelo y las criaturas que la habitan. Explora hacia el este.</p><div class="biome-grid" id="biomeGrid"></div></section></div>
 </div></main>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d',{alpha:false});
+const TILE=32,WW=360,WH=72,BIOME_W=36;
+const biomes=[
+ {name:'Pradera de Bruma',icon:'🌿',sky:['#94d4c8','#d6e8b3'],top:'#82a968',soil:'#8d714c',deep:'#63594f',accent:'#e5d78d',creature:'Brote saltarín',enemy:'#75a95d',plant:'🌼',ground:'grass'},
+ {name:'Bosque Susurrante',icon:'🌲',sky:['#7fc5b5','#c6dfa7'],top:'#4f865b',soil:'#6b6245',deep:'#484c43',accent:'#a8d59a',creature:'Polilla musgo',enemy:'#a6bd79',plant:'🌱',ground:'moss'},
+ {name:'Dunas de Cobre',icon:'🏜️',sky:['#f6c184','#f4ddb0'],top:'#d8a65e',soil:'#ba844c',deep:'#93664e',accent:'#efc774',creature:'Escarabajo ámbar',enemy:'#a9553c',plant:'🌵',ground:'sand'},
+ {name:'Ciénaga Lúgubre',icon:'🪷',sky:['#829f91','#b5bc91'],top:'#657d61',soil:'#685f4a',deep:'#48473d',accent:'#cfbb76',creature:'Sapo de linterna',enemy:'#9a7393',plant:'🪷',ground:'bog'},
+ {name:'Cumbres de Escarcha',icon:'❄️',sky:['#a9d8e2','#e1eff0'],top:'#d7e8e4',soil:'#859ba2',deep:'#5c7480',accent:'#bce9ed',creature:'Zorro níveo',enemy:'#769db4',plant:'❄',ground:'snow'},
+ {name:'Jardín de Cristal',icon:'💎',sky:['#87bfd0','#dbd8ee'],top:'#67a5ad',soil:'#617d8b',deep:'#454d66',accent:'#a6e2dc',creature:'Geoda viviente',enemy:'#9c7bc8',plant:'✧',ground:'crystal'},
+ {name:'Volcán Carmesí',icon:'🌋',sky:['#d57f69','#f4bc78'],top:'#594948',soil:'#514247',deep:'#353b42',accent:'#ff8b57',creature:'Salamandra ígnea',enemy:'#de674d',plant:'🔥',ground:'lava'},
+ {name:'Mar de Nubes',icon:'☁️',sky:['#9cc9e5','#e7e4c9'],top:'#c2d8be',soil:'#a9c8b7',deep:'#829d9b',accent:'#fff2bf',creature:'Medusa celeste',enemy:'#698dc7',plant:'☁',ground:'cloud'},
+ {name:'Ruinas Umbrías',icon:'🏚️',sky:['#737d99','#c1a8ad'],top:'#70727a',soil:'#5b5964',deep:'#373c4a',accent:'#cf8da0',creature:'Centinela hueco',enemy:'#985e7c',plant:'✦',ground:'ruin'},
+ {name:'Abismo Estelar',icon:'🌌',sky:['#292f60','#855b91'],top:'#504770',soil:'#423a64',deep:'#292744',accent:'#c19bed',creature:'Errante astral',enemy:'#c077d3',plant:'✦',ground:'star'}
+];
+const blocks=[{name:'Tierra',icon:'🟫',color:'#967751',count:28},{name:'Piedra',icon:'⬛',color:'#777c7d',count:12},{name:'Madera',icon:'🪵',color:'#9c6845',count:16},{name:'Cristal',icon:'💠',color:'#70c7c1',count:8},{name:'Ladrillo',icon:'🧱',color:'#bd7661',count:10},{name:'Linterna',icon:'🏮',color:'#f0c967',count:6}];
+let map=new Uint8Array(WW*WH),biomeAt=new Uint8Array(WW),heights=new Array(WW),decor=[],entities=[],particles=[];
+let player={x:5*TILE,y:0,vx:0,vy:0,w:22,h:40,hp:100,face:1,onGround:false,invuln:0};let camera={x:0,y:0};
+let keys={},mouse={x:0,y:0,down:false},selected=0,buildMode=false,essence=0,kills=0,boss=null,bossDefeated=false,frame=0,lastSpawn=0,toastTimer=0,scale=1;
+const idx=(x,y)=>y*WW+x,inside=(x,y)=>x>=0&&x<WW&&y>=0&&y<WH;
+function biomeFor(x){return biomes[Math.max(0,Math.min(9,Math.floor(x/BIOME_W)))];}
+function rand(n){const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)}
+function generate(){
+ for(let x=0;x<WW;x++){const b=Math.floor(x/BIOME_W);biomeAt[x]=b;let h=31+Math.sin(x*.095)*2.1+Math.sin(x*.027)*3+Math.sin(x*.33)*.7;if(b===2)h-=1.5;if(b===4)h-=2;if(b===7)h-=4;if(b===9)h+=1;h=Math.round(h);heights[x]=h;
+  for(let y=h;y<WH;y++){let id=y===h?1:y<h+5?2:y<h+13?3:4;if(b===2&&y===h)id=5;if(b===4&&y===h)id=6;if(b===5&&y===h)id=7;if(b===6&&y===h)id=8;if(b===7&&y===h)id=9;if(b===8&&y===h)id=10;if(b===9&&y===h)id=11;if(y>h+3&&rand(x*WH+y*19)>.985)id=12;map[idx(x,y)]=id;}
+  if(rand(x+33)>.62)decor.push({x,y:h-1,type:rand(x*3)>0.55?'plant':'tree',variant:rand(x*9)});
+  if(b===2&&rand(x*4)>.8)decor.push({x,y:h-1,type:'cactus',variant:0});
+ }
+ player.y=(heights[5]-1)*TILE-player.h;
+}
+generate();
+const solid=(tx,ty)=>!inside(tx,ty)||map[idx(tx,ty)]!==0;
+function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=dpr;}
+addEventListener('resize',resize);resize();
+function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');toastTimer=150;}
+function updateBiomeUI(){const bx=Math.max(0,Math.min(9,Math.floor((player.x/TILE)/BIOME_W))),b=biomes[bx];document.getElementById('biomeName').textContent=b.name;document.getElementById('biomeIcon').textContent=b.icon;document.getElementById('biomeMeta').textContent=`ZONA ${String(bx+1).padStart(2,'0')} · ${player.y/TILE>heights[Math.floor(player.x/TILE)]?'SUBSUELO':'SUPERFICIE'}`;}
+function refreshQuest(){document.getElementById('essence').textContent=essence;document.getElementById('questNum').textContent=`${Math.min(essence,8)} / 8`;document.getElementById('questFill').style.width=`${Math.min(100,essence/8*100)}%`;document.getElementById('summonButton').disabled=essence<8||boss||bossDefeated;document.getElementById('questMain').textContent=bossDefeated?'El valle está a salvo':boss?'¡Derrota al Guardián!':essence>=8?'Invoca al Guardián':'Reúne esencia';document.getElementById('questDesc').textContent=bossDefeated?'Una nueva era comienza. Sigue explorando Brumaria.':boss?'Golpéalo con J o con el botón ATACAR.':essence>=8?'Pulsa Guardián para iniciar el desafío.':'Derrota criaturas para despertar al Guardián de Raíces.';}
+function renderHotbar(){const h=document.getElementById('hotbar');h.innerHTML='';blocks.forEach((b,i)=>{const s=document.createElement('button');s.className='slot'+(i===selected?' selected':'');s.innerHTML=`<span class="keycap">${i+1}</span><span class="slot-icon">${b.icon}</span><span class="slot-name">${b.name}</span><span class="slot-count">${b.count}</span>`;s.onclick=()=>{selected=i;renderHotbar()};h.appendChild(s)});}
+renderHotbar();

