renderHotbar();
function rectHits(x,y,w,h){let l=Math.floor(x/TILE),r=Math.floor((x+w-1)/TILE),t=Math.floor(y/TILE),b=Math.floor((y+h-1)/TILE);for(let yy=t;yy<=b;yy++)for(let xx=l;xx<=r;xx++)if(solid(xx,yy))return true;return false;}
function movePlayer(){let dir=(keys.right||keys.ArrowRight?1:0)-(keys.left||keys.ArrowLeft?1:0);player.vx=dir*3.1;if(dir)player.face=dir;player.vy=Math.min(11,player.vy+.48);let nx=player.x+player.vx;if(!rectHits(nx,player.y,player.w,player.h))player.x=nx;else player.vx=0;let ny=player.y+player.vy;player.onGround=false;if(!rectHits(player.x,ny,player.w,player.h))player.y=ny;else{if(player.vy>0){player.onGround=true;player.y=Math.floor((player.y+player.h)/TILE)*TILE-player.h;}player.vy=0;}player.x=Math.max(TILE,Math.min((WW-2)*TILE,player.x));if(player.invuln>0)player.invuln--;if(player.hp<=0){player.hp=100;player.x=5*TILE;player.y=(heights[5]-1)*TILE-player.h;player.vx=player.vy=0;essence=Math.max(0,essence-1);showToast('Te reagrupas en el campamento…');refreshQuest();}}
function spawnEnemy(x,force=false){let bx=Math.max(0,Math.min(9,Math.floor(x/BIOME_W))),b=biomes[bx],tx=Math.max(2,Math.min(WW-3,Math.floor(x)));let ex=tx*TILE,ey=(heights[tx]-1)*TILE;if(Math.abs(ex-player.x)<110&&!force)return;entities.push({x:ex,y:ey,w:25,h:25,hp:2,max:2,spd:.6+rand(frame+tx)*.5,color:b.enemy,name:b.creature,boss:false,phase:rand(tx+frame)*6,hit:0});}
function summonBoss(){if(essence<8||boss)return;essence-=8;let tx=Math.min(WW-4,Math.floor(player.x/TILE)+12);boss={x:tx*TILE,y:(heights[tx]-1)*TILE-18,w:56,h:58,hp:24,max:24,spd:1.05,hit:0,phase:0};entities.push(boss);document.getElementById('bossHealth').classList.add('show');showToast('¡El Guardián de Raíces despierta!');refreshQuest();}
function attack(){let target=null,dist=68;for(const e of entities){let d=Math.hypot((e.x+e.w/2)-(player.x+player.w/2),(e.y+e.h/2)-(player.y+player.h/2));if(d<dist){dist=d;target=e;}}if(target){target.hp-=target.boss?1:2;target.hit=8;burst(target.x+target.w/2,target.y+target.h/2,'#ffe49a',8);if(target.hp<=0){entities=entities.filter(e=>e!==target);if(target.boss){boss=null;bossDefeated=true;document.getElementById('bossHealth').classList.remove('show');showToast('¡Victoria! El Guardián deja un corazón de raíz.');}else{essence++;kills++;if(kills%3===0)blocks[0].count+=2;showToast(`+1 esencia · ${target.name} derrotado`);}refreshQuest();}}else showToast('No hay criatura al alcance');}
function burst(x,y,color,n=6){for(let i=0;i<n;i++)particles.push({x,y,vx:(rand(frame+i*4)-.5)*5,vy:-rand(frame+i*2)*4-1,life:25+rand(i)*20,color});}
function targetTile(){return{x:Math.floor((mouse.x+camera.x)/TILE),y:Math.floor((mouse.y+camera.y)/TILE)}}
function interact(place){let p=targetTile(),px=player.x+player.w/2,py=player.y+player.h/2,tx=(p.x+.5)*TILE,ty=(p.y+.5)*TILE;if(Math.hypot(tx-px,ty-py)>TILE*5){showToast('Acércate un poco más');return;}if(place){let b=blocks[selected];if(b.count<=0){showToast(`Sin ${b.name.toLowerCase()} · mina para conseguir`);return;}if(!inside(p.x,p.y)||map[idx(p.x,p.y)]!==0){showToast('Ese espacio está ocupado');return;}let box={x:p.x*TILE,y:p.y*TILE,w:TILE,h:TILE};if(player.x<box.x+box.w&&player.x+player.w>box.x&&player.y<box.y+box.h&&player.y+player.h>box.y){showToast('No puedes construir sobre ti');return;}map[idx(p.x,p.y)]=[13,14,15,16,17,18][selected];b.count--;renderHotbar();burst(tx,ty,'#d7e8b5',4);}else{if(!inside(p.x,p.y)||!map[idx(p.x,p.y)])return;const id=map[idx(p.x,p.y)];map[idx(p.x,p.y)]=0;let typ=id===1||id===2?0:id===3||id===4?1:id>=5&&id<=12?3:0;blocks[typ].count++;renderHotbar();burst(tx,ty,blocks[typ].color,5);}}
function enemyUpdate(){for(const e of [...entities]){e.phase+=.05;if(e.hit)e.hit--;let dx=player.x-e.x;if(Math.abs(dx)<350){e.x+=Math.sign(dx)*e.spd;e.y=(heights[Math.max(0,Math.min(WW-1,Math.floor(e.x/TILE)))]-1)*TILE-(e.boss?18:0);if(Math.abs(dx)<e.w+player.w&&Math.abs(player.y-e.y)<40&&player.invuln===0){player.hp-=e.boss?12:7;player.invuln=38;player.vx=Math.sign(-dx)*3;document.getElementById('hpText').textContent=`${player.hp} / 100`;document.getElementById('hpFill').style.width=`${player.hp}%`;}}}if(boss){document.getElementById('bossFill').style.width=`${Math.max(0,boss.hp/boss.max*100)}%`;}}
function spawnUpdate(){let bx=Math.floor(player.x/TILE/BIOME_W);if(frame-lastSpawn>220&&entities.length<6){let tx=Math.min(WW-4,Math.max(2,Math.floor(player.x/TILE)+(Math.random()>.5?17:-17)));if(Math.floor(tx/BIOME_W)===bx)tx=Math.min(WW-4,tx+BIOME_W);spawnEnemy(tx,true);lastSpawn=frame;}}
function rgbMix(hex,amount){return hex;}
function tileColor(id,b){if(id===1)return b.top;if(id===2)return b.soil;if(id===3)return b.deep;if(id===4)return '#383c40';if(id===5)return '#d8a65e';if(id===6)return '#dcebea';if(id===7)return '#65b9b8';if(id===8)return '#574344';if(id===9)return '#b7d4ce';if(id===10)return '#696873';if(id===11)return '#554b74';if(id===12)return '#514b59';const custom={13:'#967751',14:'#777c7d',15:'#9c6845',16:'#70c7c1',17:'#bd7661',18:'#f0c967'};return custom[id]||b.soil;}
function drawBackground(w,h,biome,cx){let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,biome.sky[0]);grad.addColorStop(1,biome.sky[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);let night=Math.floor((player.x/TILE)/BIOME_W)===9;if(night){for(let i=0;i<60;i++){let x=(i*173-cx*.12)%(w+40);if(x<0)x+=w+40;let y=(i*71)%Math.max(160,h*.6);ctx.fillStyle=i%4?'#f7ddff99':'#fff4c9';ctx.fillRect(x,y,2,2);}}
 // soft distant hill silhouettes
 for(let layer=0;layer<3;layer++){let base=h*.52+layer*31;ctx.beginPath();ctx.moveTo(0,h);for(let x=0;x<=w+20;x+=20){let wx=x+cx*(.12+layer*.09);let yy=base+Math.sin(wx*.006+layer*1.8)*26+Math.sin(wx*.017)*11;ctx.lineTo(x,yy);}ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=['#ffffff18','#214c4b20','#183e3c2b'][layer];ctx.fill();}
}
function drawDecor(viewW,viewH){for(const d of decor){let sx=d.x*TILE-camera.x,sy=d.y*TILE-camera.y;if(sx<-50||sx>viewW+50)continue;const b=biomes[biomeAt[d.x]];if(d.type==='tree'){let trunk=b.ground==='snow'?'#665b53':'#72553d';ctx.fillStyle=trunk;ctx.fillRect(sx+13,sy-55,7,56);ctx.fillStyle=b.ground==='snow'?'#edf4e9':b.ground==='sand'?'#8f9c59':b.ground==='lava'?'#a24a3b':b.ground==='star'?'#7161a3':'#557c58';ctx.beginPath();ctx.arc(sx+17,sy-52,21,0,Math.PI*2);ctx.arc(sx+6,sy-39,15,0,Math.PI*2);ctx.arc(sx+29,sy-40,16,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff25';ctx.fillRect(sx+6,sy-57,4,8);}else{ctx.font=d.type==='cactus'?'25px serif':'17px serif';ctx.textAlign='center';ctx.fillText(d.type==='cactus'?'🌵':b.plant,sx+16,sy+3);}}
}

